import type OpenFin from '@openfin/core';

import { focusManager } from '@common/services/focus-manager';
import { FOCUS_PRIORITY } from '@common/types/focus';

import { getViewNameFromTabId } from './layout';
import { isOSWindows } from './os';

export const handleEscapeHotkey = async (
    e: OpenFin.Events.ViewEvents.HotkeyEvent,
    isWindows: boolean
): Promise<void> => {
    if (e.inputType === 'keyDown' && e.shiftKey && (isWindows ? e.ctrlKey : e.metaKey)) {
        if (e.key === 'E' || e.key === 'e') {
            focusManager.requestFocus({
                target: { type: 'window' },
                priority: FOCUS_PRIORITY.VIEW,
                source: 'user-click'
            });
        }
    }
};

export const handleViewHotkey = async (e: OpenFin.Events.ViewEvents.HotkeyEvent) => {
    const isWindows = await isOSWindows();
    await handleEscapeHotkey(e, isWindows);
};

/**
 * Adds a keydown listener to the element so that Enter or Space focuses the active view in the stack.
 * Used when focus is on the view container (lm_items) to allow keyboard users to move focus into the view content.
 */
export const setupViewFocusKeyboardHandler = (element: HTMLElement, fallbackViewIdentity: OpenFin.Identity): void => {
    if (!element.dataset.viewFocusHandler) {
        element.addEventListener('keydown', async (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                const activeTab = element.closest('.lm_stack')?.querySelector('.lm_tab.lm_active');
                const viewIdentity = activeTab?.id
                    ? { uuid: fin.me.uuid, name: getViewNameFromTabId(activeTab.id) }
                    : fallbackViewIdentity;

                focusManager.requestFocus({
                    target: { type: 'view', identity: viewIdentity },
                    priority: FOCUS_PRIORITY.VIEW,
                    source: 'programmatic'
                });
            }
        });
        element.dataset.viewFocusHandler = 'true';
    }
};
