import { useCallback, useEffect, useRef, useState } from 'react';

import { getAICompanionViewIdentity } from '@common/utils/enterpriseBrowser';
import { addLayoutEventListener } from '@common/utils/layout';

import { SidePanelComponent, useShouldHidePanelComponent } from '@enterprise/context/SidePanelContext';

import { AICompanionPanelId } from './AICompanionPanel';

type InboundAIChannelMessage = {
    topic: 'new-chat-button';
    showNewChatButton: boolean;
};

type OutboundAIChannelMessage = {
    topic: 'new-chat-button-clicked';
};

/**
 * Custom hook to initialize and manage the AI Companion view within the side panel.
 *
 * This hook:
 * - Attaches the AI Companion view to the current window and binds it to the AI Companion panel's DOM element.
 * - Listens for layout container resize events and rebinds the view to the panel element.
 * - Toggles the visibility of the AI Companion view based on whether the panel should be hidden.
 * - Listens for messages on a broadcast channel to update the state of the "New Chat" button.
 * - Provides a handler to notify when the "New Chat" button is clicked.
 *
 * @returns {{
 *   hidden: boolean,
 *   showNewChatButton: boolean,
 *   handleNewChatClicked: () => void
 * }} An object containing:
 * - `hidden`: A boolean indicating whether the AI Companion panel is hidden.
 * - `showNewChatButton`: A boolean indicating whether the "New Chat" button should be shown.
 * - `handleNewChatClicked`: A function to notify that the "New Chat" button has been clicked.
 */
export const useInitializeAICompanionView = () => {
    const hidden = useShouldHidePanelComponent(SidePanelComponent.AICompanion);
    const broadcastChannel = useRef<BroadcastChannel>();

    const [showNewChatButton, setShowNewChatButton] = useState<boolean>(false);

    const handleChannelMessage = useCallback(({ data }: MessageEvent<InboundAIChannelMessage>) => {
        if (data.topic === 'new-chat-button') {
            setShowNewChatButton(data.showNewChatButton);
        }
    }, []);

    useEffect(() => {
        const attachAICompanionView = async () => {
            const aiCompanionView = fin.View.wrapSync(getAICompanionViewIdentity());
            await aiCompanionView.attach(fin.me.identity);
            const aiCompanionPanelDiv = document.getElementById(AICompanionPanelId);
            await aiCompanionView.bindToElement(aiCompanionPanelDiv);
            addLayoutEventListener('container-resized', () => aiCompanionView.bindToElement(aiCompanionPanelDiv));
        };

        attachAICompanionView();
        broadcastChannel.current = new BroadcastChannel(`ai-companion-${fin.me.identity.name}`);
        broadcastChannel.current.onmessage = handleChannelMessage;
    }, []);

    useEffect(() => {
        const aiCompanionView = fin.View.wrapSync(getAICompanionViewIdentity());
        if (hidden) {
            aiCompanionView.hide();
        } else {
            aiCompanionView.show();
        }
    }, [hidden]);

    const handleNewChatClicked = useCallback(() => {
        broadcastChannel.current.postMessage({ topic: 'new-chat-button-clicked' } as OutboundAIChannelMessage);
    }, []);

    return { hidden, showNewChatButton, handleNewChatClicked };
};
