import type OpenFin from '@openfin/core';

/**
 * Represents different focus targets in the application
 */
export type FocusTarget =
    | { type: 'view'; identity: OpenFin.Identity }
    | { type: 'addressBar' }
    | { type: 'window' }
    | { type: 'modal'; name: string };

/**
 * The source of a focus request
 */
export type FocusSource = 'user-click' | 'openfin-event' | 'programmatic' | 'navigation';

/**
 * Priority levels for focus requests
 */
export const FOCUS_PRIORITY = {
    LOW: 10,
    VIEW: 30,
    ADDRESS_BAR: 50,
    MODAL: 100
} as const;

/**
 * Standard debounce timing for all focus operations
 */
export const FOCUS_DEBOUNCE_MS = 50;

/**
 * A focus request with all necessary metadata
 */
export interface FocusRequest {
    target: FocusTarget;
    priority: number;
    source: FocusSource;
}
