import React, { createContext, useContext, useEffect, useState } from 'react';

import { OpenFin } from '@openfin/core';

export type EnterpriseSettings = {
    aiCompanion: {
        enabled: boolean;
    };
    bookmarks: {
        enabled: boolean;
    };
    addressBar: {
        enabled: boolean;
    };
};

const defaultSettings: EnterpriseSettings = {
    aiCompanion: {
        enabled: false
    },
    bookmarks: {
        enabled: true
    },
    addressBar: {
        enabled: true
    }
};
export const EnterpriseSettingsContext = createContext<EnterpriseSettings>(defaultSettings);

export const EnterpriseSettingsProvider = (props: { children: React.ReactNode }) => {
    const [enterpriseSettings, setEnterpriseSettings] = useState<EnterpriseSettings>(defaultSettings);

    useEffect(() => {
        (async () => {
            const { workspacePlatform } = await (fin.me as OpenFin.Window).getOptions();
            setEnterpriseSettings({
                aiCompanion: {
                    enabled: !!workspacePlatform.enterprise?.aiCompanion?.enabled
                },
                bookmarks: {
                    enabled: !!workspacePlatform.enterprise?.bookmarks?.enabled
                },
                addressBar: {
                    enabled: !!workspacePlatform.enterprise?.addressBar?.enabled
                }
            });
        })();
    }, []);

    return (
        <EnterpriseSettingsContext.Provider value={enterpriseSettings}>
            {props.children}
        </EnterpriseSettingsContext.Provider>
    );
};

export const useEnterpriseSettings = () => useContext(EnterpriseSettingsContext);
