import type OpenFin from '@openfin/core';

import { getAddressBarInputElement } from '@common/utils/address-bar-focus';
import { createInlineDebugLogger } from '@common/utils/debug-log';
import { createLogger } from '@common/utils/logger';
import { menuEvents } from '@common/utils/menu-window-provider';

const logger = createLogger('common.focusManager');

import type { FocusRequest, FocusTarget } from '../types/focus';
import { FOCUS_DEBOUNCE_MS, FOCUS_PRIORITY } from '../types/focus';

const logFocusDebug = createInlineDebugLogger('focus-debug');

/**
 * Get the inherent priority of a target type.
 * Used to determine precedence when different target types compete.
 */
const getInherentTypePriority = (targetType: FocusTarget['type']): number => {
    switch (targetType) {
        case 'modal':
            return FOCUS_PRIORITY.MODAL;
        case 'view':
            return FOCUS_PRIORITY.VIEW;
        case 'addressBar':
            return FOCUS_PRIORITY.ADDRESS_BAR;
        case 'window':
            return FOCUS_PRIORITY.LOW;
        default:
            return FOCUS_PRIORITY.LOW;
    }
};

/**
 * Centralized focus management service for OpenFin windows and views.
 *
 * This service provides a single source of truth for focus management across the application,
 * handling:
 * - Priority-based focus requests
 * - Debouncing to prevent race conditions
 * - Blockers (modals, etc.) that prevent focus changes
 * - Prevention of re-focus loops from OpenFin events
 *
 * @example
 * ```typescript
 * import { focusManager } from '@common/services/focus-manager';
 *
 * // Request focus on a view
 * focusManager.requestFocus({
 *   target: { type: 'view', identity: { uuid: 'app', name: 'view1' } },
 *   priority: FOCUS_PRIORITY.VIEW,
 *   source: 'user-click',
 *   debounceMs: FOCUS_DEBOUNCE.FAST
 * });
 * ```
 */
class FocusManager {
    private currentFocus: FocusTarget | null = null;
    private blockers = new Set<string>();
    private pendingRequest: ReturnType<typeof setTimeout> | null = null;
    private pendingPriority: number | null = null;
    private pendingTarget: FocusTarget | null = null;

    constructor() {
        // Add/remove search menu blockers via search menu events
        menuEvents.addListener('search-menu-opening', () => {
            this.addBlocker('search-menu');
        });
        menuEvents.addListener('search-menu-closed', () => {
            this.removeBlocker('search-menu');
        });
    }

    private log(event: string, data?: Record<string, unknown>): void {
        logFocusDebug(event, data);
    }

    /**
     * Request focus on a target. Priority determines which request wins.
     *
     * If source is 'openfin-event', we skip the actual .focus() call
     * to avoid re-focus loops since OpenFin has already focused the element.
     *
     * All requests use a standard 50ms debounce to enable priority comparison
     * and coalesce rapid actions.
     *
     * Priority handling:
     * - Same target type: Compare request.priority values
     * - Different target types: Compare inherent type priorities (modal > view > addressBar > window)
     *
     * @param request - The focus request with target, priority, and source
     */
    requestFocus(request: FocusRequest): void {
        const logMessage: any = {
            target: request.target.type,
            priority: request.priority,
            source: request.source
        };
        if (request.target.type === 'view') {
            logMessage.identity = request.target.identity;
        }
        this.log('Focus requested', logMessage);

        // Check if there's a pending request with higher priority
        if (this.pendingRequest && this.pendingPriority !== null && this.pendingTarget) {
            const sameTargetType = this.pendingTarget.type === request.target.type;

            if (sameTargetType) {
                // Priority comparison only applies within the same target type
                if (request.priority < this.pendingPriority) {
                    this.log(
                        `Ignoring lower priority request (${request.priority} < ${this.pendingPriority}) for same target type '${request.target.type}'`
                    );
                    return;
                }
                // New request has equal or higher priority, cancel the old one
                this.log(
                    `Cancelling pending request (new priority ${request.priority} >= ${this.pendingPriority}) for same target type '${request.target.type}'`
                );
            } else {
                // Different target types - compare inherent type priorities
                const pendingTypePriority = getInherentTypePriority(this.pendingTarget.type);
                const newTypePriority = getInherentTypePriority(request.target.type);

                if (newTypePriority < pendingTypePriority) {
                    // New target type has lower inherent priority - ignore it
                    this.log(
                        `Ignoring request: target type '${request.target.type}' (priority ${newTypePriority}) has lower priority than pending '${this.pendingTarget.type}' (priority ${pendingTypePriority})`
                    );
                    return;
                }

                // New target type has equal or higher inherent priority - cancel pending
                this.log(
                    `Cancelling pending request: target type '${request.target.type}' (priority ${newTypePriority}) has higher/equal priority than '${this.pendingTarget.type}' (priority ${pendingTypePriority})`
                );
            }

            clearTimeout(this.pendingRequest);
            this.pendingRequest = null;
            this.pendingPriority = null;
            this.pendingTarget = null;
        }

        const execute = () => {
            // Clear pending state
            this.pendingRequest = null;
            this.pendingPriority = null;
            this.pendingTarget = null;

            // Check blockers first
            if (this.blockers.size > 0) {
                this.log('Focus blocked by', { blockers: Array.from(this.blockers).join('|') });
                return;
            }

            // Don't re-focus if already focused via OpenFin event
            if (request.source === 'openfin-event') {
                this.log('Focus from OpenFin event, updating state only');
                this.currentFocus = request.target;
                return;
            }

            // Execute the actual focus
            this.log(
                `Applying focus to ${
                    request.target.type === 'view' ? `view ${request.target.identity.name}` : request.target.type
                }`
            );
            this.applyFocus(request.target);
            this.currentFocus = request.target;
        };

        this.pendingRequest = setTimeout(execute, FOCUS_DEBOUNCE_MS);
        this.pendingPriority = request.priority;
        this.pendingTarget = request.target;
    }

    /**
     * Focus a view, first activating its tab in its stack so the focus is meaningful.
     *
     * Use this when the user explicitly switches to a view (e.g. selecting it from tab search).
     * Plain {@link requestFocus} focuses a view with `emitSynthFocused: false` to avoid page-switch
     * loops, so on its own it will NOT bring a background tab to the front. This method first calls
     * `TabStack.setActiveView` so the chosen tab becomes visible, then delegates to {@link requestFocus}
     * for the focus itself.
     *
     * Activation runs immediately and is intentionally NOT subject to focus blockers or the
     * debounce/priority pipeline — a user's explicit "go to this tab" intent must not be cancelled by
     * an active focus blocker. Only the subsequent focus goes through the normal pipeline.
     *
     * @param identity - Identity of the view to focus and activate.
     */
    async focusAndActivateView(identity: OpenFin.Identity): Promise<void> {
        this.log('Focus and activate view requested', { identity });

        try {
            const stack = await fin.View.wrapSync(identity).getCurrentStack();
            await stack.setActiveView(identity);
        } catch (error) {
            logger.error('focusAndActivateView', 'Failed to activate view in its stack', {
                error,
                identity
            });
        }

        this.requestFocus({
            target: { type: 'view', identity },
            priority: FOCUS_PRIORITY.VIEW,
            source: 'navigation'
        });
    }

    /**
     * Apply focus to the target element
     */
    private applyFocus(target: FocusTarget): void {
        try {
            switch (target.type) {
                case 'view':
                    // Container calls showLayout() when synth-focused event is emitted,
                    // which can cause unintended setting of active page. Avoid emitting to prevent page switch loops.
                    fin.View.wrapSync(target.identity).focus({ emitSynthFocused: false });
                    break;

                case 'addressBar': {
                    const addressBar = getAddressBarInputElement();
                    if (addressBar) {
                        // Focus window first, then input
                        fin.Window.getCurrentSync().focus();
                        addressBar.focus();
                    }
                    break;
                }

                case 'window':
                    fin.Window.getCurrentSync().focus();
                    break;

                case 'modal':
                    // Modals handle their own focus via FocusTrap
                    this.log('Modal focus handled by FocusTrap');
                    break;
            }
        } catch (error) {
            console.error('[FocusManager] Error applying focus:', error);
        }
    }

    /**
     * Add a blocker that prevents focus changes
     * @param name - Unique identifier for the blocker (e.g., 'modal', 'zoom-dialog')
     */
    addBlocker(name: string): void {
        this.log(`Adding blocker ${name}`);
        this.blockers.add(name);
    }

    /**
     * Remove a blocker to allow focus changes again
     * @param name - Unique identifier for the blocker
     */
    removeBlocker(name: string): void {
        this.log(`Removing blocker ${name}`);
        this.blockers.delete(name);
    }

    /**
     * Get the current focus target
     */
    getCurrentFocus(): FocusTarget | null {
        return this.currentFocus;
    }

    /**
     * Clear the current focus state
     */
    clearFocus(): void {
        this.log('Clearing focus state');
        this.currentFocus = null;
        if (this.pendingRequest) {
            clearTimeout(this.pendingRequest);
            this.pendingRequest = null;
            this.pendingPriority = null;
            this.pendingTarget = null;
        }
    }

    /**
     * Check if there are any active blockers
     */
    hasBlockers(): boolean {
        return this.blockers.size > 0;
    }

    /**
     * Cancel any pending focus requests
     */
    cancelPending(): void {
        if (this.pendingRequest) {
            clearTimeout(this.pendingRequest);
            this.pendingRequest = null;
            this.pendingPriority = null;
            this.pendingTarget = null;
            this.log('Cancelled pending focus request');
        }
    }
}

// Export singleton instance
export const focusManager = new FocusManager();
