import { WheelEvent } from 'react';

import { currentOFIdentity } from '@common/utils/window';

import type { AttachedPage, AttachedPageInternal } from '@common/api/pages/shapes';

import { updatePageForViewCount } from '@enterprise/utils/layout';

import { getCurrentSync } from '@client-platform/api';
import type { BrowserWorkspacePlatformWindowOptions } from '@client-platform/shapes';

/**
 * Gets the index of the page that should be active once current active page is removed.
 * @param detachedActivePageIndex Index of the active page prior to being removed
 * @param filteredPages Remaining pages
 * @returns page that should be active once current active page is removed
 */
export const getNextActivePageOnRemoval = (detachedActivePageIndex: number, filteredPages: AttachedPage[]) => {
    let newActiveIndex = detachedActivePageIndex > 0 ? detachedActivePageIndex - 1 : 0;
    if (newActiveIndex >= filteredPages.length) {
        newActiveIndex = filteredPages.length - 1;
    }
    return filteredPages[newActiveIndex];
};

/**
 * Derives workspace window options from platform options.
 */
export const deriveWorkspaceWindowOpts = (wp: BrowserWorkspacePlatformWindowOptions) => ({
    isLocked: !!wp?.isLocked,
    preventPageDragIn: !!wp?.preventPageDragIn,
    preventPageDragOut: !!wp?.preventPageDragOut,
    preventPageDrag: !!wp?.preventPageDrag,
    preventPageClose: !!wp?.preventPageClose,
    disableMultiplePages: !!wp?.disableMultiplePages,
    documentTitle: wp?.title || '',
    isNewPageButtonEnabled: !!wp?.newPageUrl
});

/**
 * Brings the current window to the front.
 */
export const bringWindowToFront = async (): Promise<void> => {
    await fin.Window.getCurrentSync().bringToFront();
};

/**
 * Hides golden layouts drag indicators when dragging a view into a high level tab.
 * This is a workaround to hide golden layouts drag indicators when dragging a view into a high level tab.
 * This should only happen in the enterprise version.
 */
export const hideGoldenLayoutsDragIndicators = (): void => {
    const goldenLayoutsTargetIndicator = document.getElementsByClassName('lm_dropTargetIndicator');
    const goldenLayoutsTransitionIndicator = document.getElementsByClassName('lm_transition_indicator');
    if (goldenLayoutsTargetIndicator) {
        for (let i = 0; i < goldenLayoutsTargetIndicator.length; i++) {
            goldenLayoutsTargetIndicator[i].setAttribute('style', '');
        }
    }
    if (goldenLayoutsTransitionIndicator) {
        for (let i = 0; i < goldenLayoutsTransitionIndicator.length; i++) {
            goldenLayoutsTransitionIndicator[i].setAttribute('style', '');
        }
    }
};

/**
 * Handles horizontal scrolling for the tab container when vertical wheel events occur.
 */
export const handleTabContainerScroll = (event: WheelEvent<HTMLDivElement>): void => {
    const { deltaX, deltaY } = event;
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
        event.currentTarget.scrollLeft += deltaY - deltaX;
    }
};

export const mergeViewIntoTargetPage = async (
    targetPage: AttachedPageInternal,
    viewOptions: any,
    updatedActivePage: AttachedPageInternal
) => {
    const targetLayout = fin.Platform.Layout.wrapSync({
        ...currentOFIdentity,
        layoutName: targetPage.layoutContainerKey
    });
    await getCurrentSync().Browser.wrapSync(currentOFIdentity).setActivePage(targetPage.pageId);
    const root = await targetLayout.getRootItem();
    await root.createAdjacentStack([viewOptions], { position: 'right' });

    if (targetPage.pageId !== updatedActivePage.pageId) {
        // If targetPage and activePage are the same, updatePageForViewCountListener will handle this update.
        // Update activePage before targetPage so that activePage can give up its default name before targetPage gets one.
        // Use the immediate (non-debounced) variant: the shared debounced function can only
        // track one pending page at a time, so back-to-back calls for different pages would
        // silently swallow all but the last.
        updatePageForViewCount(updatedActivePage, true);
        updatePageForViewCount(targetPage, true);
    }
};
