import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import { countViews } from '@common/utils/layout';
import { raiseBrowserPageAnalytics } from '@common/utils/usage-register';

import type { AttachedPage, AttachedPageInternal, ExtendedPanelConfig } from '@common/api/pages/shapes';

/**
 * Interface for the parameters needed to attach pages to a window
 */
export interface AttachPagesParams {
    /** The pages to attach */
    pages: AttachedPage[];
    /** The existing pages in the window */
    existingPages: AttachedPage[];
    /** Optional index where to insert the new pages */
    insertionIndex?: number;
    /** Whether to replace the active page with the first new page */
    replaceActivePage?: boolean;
    /** Function to attach panel views */
    attachPanelViews: (panels: ExtendedPanelConfig[]) => Promise<void>;
    /** Function to dispatch Redux actions */
    dispatch: (action: any) => void;
    /** Function to update pages window options */
    updatePagesWindowOptions: () => Promise<void>;
    /** Function to set pages in Redux state */
    setPages: (pages: AttachedPage[]) => void;
    /** Function to update a page at a specific index */
    updatePageAtIndex: (params: { index: number; page: Partial<AttachedPageInternal> }) => void;
}

/**
 * Interface for the result of attaching pages
 */
export interface AttachPagesResult {
    /** The new attached pages with proper metadata */
    newAttachedPages: AttachedPage[];
    /** The updated pages state */
    newPagesState: AttachedPage[];
}

/**
 * Creates new attached pages with proper metadata and validation
 *
 * @param pages - The pages to attach
 * @param existingPages - The existing pages in the window
 * @returns Array of new attached pages with proper metadata
 */
export const createNewAttachedPages = async (
    pages: AttachedPage[],
    existingPages: AttachedPage[]
): Promise<AttachedPage[]> => {
    const isEnterprise = await isEnterpriseBrowser();

    return pages.map((page) => {
        const alreadyExists = existingPages.find((p) => p.pageId === page.pageId);
        if (alreadyExists) {
            throw new Error(`Target window already has a page with pageId: ${page.pageId}`);
        }

        const viewCount = isEnterprise ? countViews(page.layout.content) : 0;

        return {
            ...page,
            parentIdentity: fin.me.identity,
            isActive: false,
            // only setting multiView here if there are more than one views, otherwise it will be undefined until the layout is created in order to avoid getting singleView title by wrong view id
            attachedPageType: viewCount > 1 ? 'multiView' : undefined
        };
    });
};

/**
 * Handles panel reparenting for pages that need to be reparented
 *
 * @param newAttachedPages - The new attached pages
 * @param attachPanelViews - Function to attach panel views
 */
export const handlePanelReparenting = async (
    newAttachedPages: AttachedPage[],
    attachPanelViews: (panels: ExtendedPanelConfig[]) => Promise<void>
): Promise<void> => {
    const panelsToReparent = newAttachedPages.reduce((panels: ExtendedPanelConfig[], currentPage: AttachedPage) => {
        return [...panels, ...(currentPage.panels ? currentPage.panels : [])];
    }, []);

    await attachPanelViews(panelsToReparent);
};

/**
 * Updates the pages state based on replaceActivePage logic
 *
 * @param existingPages - The existing pages in the window
 * @param newAttachedPages - The new attached pages
 * @param insertionIndex - Optional index where to insert the new pages
 * @param replaceActivePage - Whether to replace the active page
 * @returns The updated pages state
 */
export const updatePagesState = (
    existingPages: AttachedPage[],
    newAttachedPages: AttachedPage[],
    insertionIndex?: number,
    replaceActivePage?: boolean
): AttachedPage[] => {
    const newPagesState = [...existingPages];
    const activePageIndex = existingPages.findIndex((page) => page.isActive);

    if (activePageIndex !== -1) {
        // Handle replaceActivePage logic
        if (replaceActivePage) {
            // Find the currently active page
            // Remove the active page and insert new pages at its position
            newPagesState.splice(activePageIndex, 1, ...newAttachedPages);
            // Set the first new page as active
            newPagesState[activePageIndex] = {
                ...newPagesState[activePageIndex],
                isActive: true
            };
        } else {
            // Add new pages at specified index or at the end if unspecified
            const actualInsertIndex = insertionIndex ?? existingPages.length;
            newPagesState.splice(actualInsertIndex, 0, ...newAttachedPages);
        }
    } else {
        // No active page found, just add at insertion index or at the end if unspecified
        const actualInsertIndex = insertionIndex ?? existingPages.length;
        newPagesState.splice(actualInsertIndex, 0, ...newAttachedPages);
        // Set the first new page as active
        newPagesState[actualInsertIndex] = {
            ...newPagesState[actualInsertIndex],
            isActive: true
        };
    }
    return newPagesState;
};

/**
 * Sets the first new page as active in Redux state
 *
 * @param newAttachedPages - The new attached pages
 * @param newPagesState - The updated pages state
 * @param updatePageAtIndex - Function to update a page at a specific index
 */
export const setFirstPageActive = (
    newAttachedPages: AttachedPage[],
    newPagesState: AttachedPage[],
    updatePageAtIndex: (params: { index: number; page: Partial<AttachedPageInternal> }) => void
): void => {
    // Manually set the first new page as active in Redux state
    if (newAttachedPages.length > 0) {
        const firstNewPage = newAttachedPages[0];
        const firstNewPageIndex = newPagesState.findIndex((page) => page.pageId === firstNewPage.pageId);
        if (firstNewPageIndex !== -1) {
            updatePageAtIndex({
                index: firstNewPageIndex,
                page: { isActive: true }
            });
        }
    }
};

/**
 * Main function to handle attaching pages to a window
 * This function encapsulates the shared logic between browser and enterprise workspaces
 *
 * @param params - The parameters needed to attach pages
 * @returns Promise that resolves when pages are attached
 */
export const attachPagesToWindowCore = async (params: AttachPagesParams): Promise<void> => {
    const {
        pages,
        existingPages,
        insertionIndex,
        replaceActivePage,
        attachPanelViews,
        dispatch,
        updatePagesWindowOptions,
        setPages,
        updatePageAtIndex
    } = params;

    if (!pages.length) return;

    // Create new attached pages with proper metadata
    const newAttachedPages = await createNewAttachedPages(pages, existingPages);

    // Handle panel reparenting
    await handlePanelReparenting(newAttachedPages, attachPanelViews);

    // Update pages state based on replaceActivePage logic
    const newPagesState = updatePagesState(existingPages, newAttachedPages, insertionIndex, replaceActivePage);

    // Update Redux state
    dispatch(setPages(newPagesState));

    if (replaceActivePage) {
        // Set the first new page as active
        setFirstPageActive(newAttachedPages, newPagesState, updatePageAtIndex);
    }

    // Update window options and analytics
    await updatePagesWindowOptions();
    raiseBrowserPageAnalytics(newAttachedPages, 'Open Page');
};
