import { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';

import { FalseyValue } from 'styled-components';

import { addLayoutEventListener } from '@common/utils/layout';

import { PanelConfigHorizontal, PanelConfigVertical, PanelPosition } from '@common/api/pages/shapes';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { getSizeWithoutCSSUnits } from '@enterprise/components/PanelContainer/PanelContainer';
import { getSidePanelConfig } from '@enterprise/components/PanelContainer/utils';

import { useSidePanelContext } from '@enterprise/context/SidePanelContext';

/**
 * A template processor that converts falsey values to '0px'.
 * Helps avoid verbosity when writing complex CSS calc() expressions
 * @param strings slices of the template that surround values to process
 * @param values CSS measurement values, potentially falsey
 * @returns string with falsey values converted to 0px
 */
const units = (strings: TemplateStringsArray, ...values: (string | FalseyValue)[]) => {
    let result = strings[0];
    for (let i = 0; i < values.length; i++) {
        const value = values[i] || '0px';
        result += value + strings[i + 1];
    }
    return result;
};

export type CSSBounds = Partial<Record<'top' | 'right' | 'bottom' | 'left' | 'height' | 'width', string>>;

const zeroBounds: CSSBounds = { left: '0', top: '0', width: '0', height: '0' };

export const usePanelBounds = (panelPosition: PanelPosition | 'Center') => {
    const activePage = useSelector(selectActivePage);
    const [resizeCounter, setResizeCounter] = useState(0);
    const { isSidePanelOpen } = useSidePanelContext();

    const pagelessPanels: (PanelConfigHorizontal | PanelConfigVertical)[] = useMemo(() => {
        if (isSidePanelOpen) {
            return [getSidePanelConfig(false)];
        }
        return [];
    }, [isSidePanelOpen]);

    useEffect(() => {
        if (panelPosition === PanelPosition.Right || panelPosition === PanelPosition.Bottom) {
            /*
             * When resizing window along only an x or y axis, the Right/Bottom panel element doesn't resize
             * but only moves along the corresponding axis.
             * Mere position change doesn't trigger ResizeObserver and view remains in the old position.
             * We need to resize the panel by a unique tiny amount to trigger view reposition.
             */
            addLayoutEventListener('container-resized', () => setResizeCounter((currentVal) => currentVal + 1));
        }
    }, [panelPosition]);

    const cssBounds = useMemo(() => {
        const panels = activePage.panels;
        const topConfig = (panels?.find((panel) => panel.position == PanelPosition.Top) ||
            pagelessPanels?.find((panel) => panel.position == PanelPosition.Top)) as PanelConfigHorizontal | undefined;

        const leftConfig = (panels?.find((panel) => panel.position == PanelPosition.Left) ||
            pagelessPanels?.find((panel) => panel.position == PanelPosition.Left)) as PanelConfigVertical | undefined;

        const rightConfig = (panels?.find((panel) => panel.position == PanelPosition.Right) ||
            pagelessPanels?.find((panel) => panel.position == PanelPosition.Right)) as PanelConfigVertical | undefined;

        const bottomConfig = (panels?.find((panel) => panel.position == PanelPosition.Bottom) ||
            pagelessPanels?.find((panel) => panel.position == PanelPosition.Bottom)) as
            | PanelConfigHorizontal
            | undefined;

        const extendLeftPanelToTop = leftConfig?.extendToTop;
        const extendLeftPanelToBottom = leftConfig?.extendToBottom;

        const extendRightPanelToTop = rightConfig?.extendToTop;
        const extendRightPanelToBottom = rightConfig?.extendToBottom;

        switch (panelPosition) {
            case PanelPosition.Left:
                return {
                    left: '0',
                    top: units`${!extendLeftPanelToTop && topConfig?.height}`,
                    width: units`${leftConfig?.width}`,
                    height: units`calc(100% - ${!extendLeftPanelToTop && topConfig?.height} - ${
                        !extendLeftPanelToBottom && bottomConfig?.height
                    })`
                };
            case PanelPosition.Right:
                return {
                    right: '0px',
                    top: units`${!extendRightPanelToTop && topConfig?.height}`,
                    // Not resizing by tiny amount because we will rebind AI side panel view explicitly on layout resize
                    width:
                        getSizeWithoutCSSUnits(units`${rightConfig?.width}`) === 0
                            ? '0px' // no need to offset by a small value if it's a 0 sized panel
                            : `${rightConfig?.width}`,
                    height: units`calc(100% - ${!extendRightPanelToTop && topConfig?.height} - ${
                        !extendRightPanelToBottom && bottomConfig?.height
                    })`
                };
            case PanelPosition.Top:
                return {
                    left: units`${extendLeftPanelToTop && leftConfig?.width}`,
                    top: '0',
                    width: units`calc(100% - ${extendLeftPanelToTop && leftConfig?.width} - ${
                        extendRightPanelToTop && rightConfig?.width
                    })`,
                    height: units`${topConfig?.height}`
                };
            case PanelPosition.Bottom:
                return {
                    left: units`${extendLeftPanelToBottom && leftConfig?.width}`,
                    bottom: '0',
                    width: units`calc(100% - ${extendLeftPanelToBottom && leftConfig?.width} - ${
                        extendRightPanelToBottom && rightConfig?.width
                    })`,
                    // need to resize by a tiny value in order to trigger view repositioning
                    height:
                        getSizeWithoutCSSUnits(units`${bottomConfig?.height}`) === 0
                            ? '0px' // no need to offset by a small value if it's a 0 sized panel
                            : units`calc(${bottomConfig?.height} - ${(resizeCounter % 2) / 1000 + 'cm'})`
                };
            case 'Center':
                return {
                    left: units`${leftConfig?.width}`,
                    top: units`${topConfig?.height}`,
                    // If side panel is activated, we have to account for navigation rail width
                    width: units`calc(100% - ${leftConfig?.width} - ${rightConfig?.width})`,
                    height: units`calc(100% - ${topConfig?.height} - ${bottomConfig?.height})`
                };
            default:
                return zeroBounds;
        }
    }, [pagelessPanels, activePage.panels, panelPosition, resizeCounter]);

    return cssBounds;
};
