import React from 'react';

import styled, { css } from 'styled-components';

import { PanelPosition } from '@common/api/pages/shapes';

import AICompanionPanel from '@enterprise/components/PanelContainer/AICompanionPanel/AICompanionPanel';
import BookmarksPanel from '@enterprise/components/PanelContainer/BookmarksPanel/BookmarksPanel';

import { MAC_WINDOW_BORDER_RADIUS } from '@common/mixins/padding-border';
import { useEnterpriseSettings } from '@enterprise/context/EnterpriseSettings';
import { useIsWindows } from '@enterprise/hooks/useIsWindows';
import { CSSBounds, usePanelBounds } from '@enterprise/hooks/usePanelBounds';

interface Props {
    position: PanelPosition;
}

const PanelContainer: React.FC<Props> = ({ position }) => {
    const cssBounds = usePanelBounds(position);

    const { aiCompanion, bookmarks } = useEnterpriseSettings();
    const isWindows = useIsWindows();

    return (
        <Panel
            className="side-panel-container"
            {...cssBounds}
            tabIndex={0}
            id={'panel' + position}
            isWindows={isWindows}
        >
            {bookmarks.enabled && <BookmarksPanel />}
            {aiCompanion.enabled && <AICompanionPanel />}
        </Panel>
    );
};

export default PanelContainer;

export const getSizeWithoutCSSUnits = (cssValue: string | number = ''): number => {
    const stringValue = String(cssValue);
    const asNumber = Number(stringValue.replace(/[a-zA-Z]*(%)*/g, ''));
    return !Number.isNaN(asNumber) ? asNumber : null;
};

const Panel = styled.div<CSSBounds & { isWindows: boolean }>`
    height: ${({ height }) => height};
    width: ${({ width }) => width};

    left: ${({ left }) => left || 'unset'};
    right: ${({ right }) => right || 'unset'};
    top: ${({ top }) => top || 'unset'};
    bottom: ${({ bottom }) => bottom || 'unset'};

    display: ${({ width, height }) =>
        getSizeWithoutCSSUnits(width) === 0 || getSizeWithoutCSSUnits(height) === 0 ? 'none' : 'flex'};

    background-color: var(--color-enterprise-side-panel-background);
    position: absolute;
    box-sizing: ${({ isWindows }) => (isWindows ? 'border-box' : 'content-box')};
    border: 1px solid var(--color-enterprise-side-panel-border);
    margin-top: ${({ top }) => (top === '0px' ? '-1px' : '0')};
    z-index: 3;
    margin-bottom: ${({ bottom }) => (bottom === '0px' ? '-1px' : '0')};
    margin-right: ${({ right }) => (right === '0px' ? '-1px' : '0')};
    border-radius: 0;
    ${({ isWindows, width }) =>
        !isWindows &&
        css`
            border-bottom-right-radius: ${MAC_WINDOW_BORDER_RADIUS};
            box-shadow: none;
            width: ${width ? `calc(${width} - 1px)` : 'unset'};
        `}
    overflow: hidden;
`;
