import { PanelConfigVertical, PanelPosition } from '@client-platform/index';

export const NAVIGATION_RAIL_WIDTH = 40;
export const SIDE_PANEL_WIDTH = 340;

export const getSidePanelConfig = (shouldShowNavigationRail: boolean): PanelConfigVertical => {
    const sidePanelWidth = shouldShowNavigationRail ? SIDE_PANEL_WIDTH + NAVIGATION_RAIL_WIDTH : SIDE_PANEL_WIDTH;
    return {
        position: PanelPosition.Right,
        width: `${sidePanelWidth}px`
    };
};
