import type OpenFin from '@openfin/core';

import { getEnterpriseLandingUrl } from '@common/utils/browser-base-url';
import makeDebouncedFunc from '@common/utils/debounce';
import { getLayoutConfig, getUnlockedLayout, mapLayoutViewComponents } from '@common/utils/layout';
import { attachPagesToWindowCore } from '@common/utils/pages/attach-pages';
import { raiseBrowserPageAnalytics } from '@common/utils/usage-register';
import { currentOFIdentity, getCurrentOFWindow, getDisableMultiplePagesOption } from '@common/utils/window';

import {
    attachPagesToWindow as AttachPagesToWindowType,
    detachPagesFromWindow as DetachPagesFromWindowType,
    getPages as GetPagesType,
    renamePage as RenamePageType,
    reorderPagesForWindow as ReorderPagesForWindowType,
    setActivePageForWindow as SetActivePageForWindowType,
    updatePageForWindow as UpdatePageForWindowType
} from '@common/api/pages/attached';
import type { AttachedPageInternal } from '@common/api/pages/enterprise-shapes';
import type { AttachedPage, SetActivePageForWindowPayload } from '@common/api/pages/shapes';

import { dispatch, getState } from '@enterprise/api/pages/state';
import {
    selectActivePage,
    selectActivePageIndex,
    selectIsActivePageChanging,
    selectPage,
    selectPages,
    selectPageWithIndex,
    setIsActivePageChanging,
    setPages,
    updatePageAtIndex
} from '@enterprise/slices/pages/attached';

import { replaceLayout } from '@enterprise/utils/layout';

import { deletePageWithSelectedViews } from '@enterprise/slices/tab-focus';

import { getNextActivePageOnRemoval } from '@enterprise/components/ControlBar/Tablist/utils';

import { getCurrentSync } from '@client-platform/api';
import { applyEnterprisePageRequiredLayoutSettings } from '@client-platform/init/override-callback/enterprise-page-required-layout-settings';
import { mapInternalWorkspaceDataToWorkspacePlatform } from '@client-platform/init/override-callback/view-options';

import { attachPanelViews, getPanelsWithViewSnapshots, setUpPanelViews } from '../panels';

/**
 * Save the current attached page state in window options.
 */
export const updatePagesWindowOptions = makeDebouncedFunc(async () => {
    /*
     * Always get state from redux store because we need to preserve internal
     * properties (e.g. layoutContainerKey) for provider snapshot logic
     */
    const attachedPages = selectPages(getState());
    const oldOptions = await (fin.me as OpenFin.Window).getOptions();

    await fin.me.updateOptions({
        workspacePlatform: {
            ...oldOptions.workspacePlatform,
            pages: (await Promise.all(
                attachedPages.map(async (page) => {
                    return {
                        ...page,
                        parentIdentity: undefined,
                        isSaved: undefined,
                        panels: await getPanelsWithViewSnapshots(page.panels)
                    };
                })
            )) as AttachedPage[]
        }
    });
});

const handleSetActivePageForWindow = async ({ pageId }: SetActivePageForWindowPayload) => {
    try {
        const disableMultiplePages = !!(await getDisableMultiplePagesOption(fin.me));

        const state = getState();
        const currentActivePage = selectActivePage(state);
        const currentActivePageIndex = selectActivePageIndex(state);
        if (currentActivePage?.pageId === pageId) {
            if (!currentActivePage?.isLayoutCreated) {
                dispatch(
                    updatePageAtIndex({
                        index: currentActivePageIndex,
                        page: { isLayoutCreated: true }
                    })
                );
            }
            return;
        }

        if (disableMultiplePages) {
            throw new Error('Cannot change active page in a browser window where disableMultiplePages is true');
        }

        dispatch(setIsActivePageChanging(true));

        const [newActivePage, newActivePageIndex] = selectPageWithIndex(getState(), pageId);
        if (!newActivePage) {
            throw new Error(`page with id ${pageId} is not attached to window ${fin.me.identity.name}`);
        }
        await setUpPanelViews(newActivePage.panels, currentActivePage?.panels);

        await updatePagesWindowOptions();
        dispatch(
            updatePageAtIndex({
                index: currentActivePageIndex,
                page: { isActive: false, isLayoutCreated: true }
            })
        );

        dispatch(
            updatePageAtIndex({
                index: newActivePageIndex,
                page: { isActive: true, isLayoutCreated: true }
            })
        );

        if (currentActivePage) {
            const layout = fin.Platform.Layout.wrapSync({
                ...fin.me.identity,
                layoutName: currentActivePage.layoutContainerKey
            });

            const currentLayout = await layout.getConfig();

            const layoutConfig = currentActivePage.isLocked
                ? // never store locked layout settings in memory
                  getUnlockedLayout(currentLayout, currentActivePage.layout)
                : currentLayout;

            dispatch(
                updatePageAtIndex({
                    index: currentActivePageIndex,
                    page: { isActive: false, layout: layoutConfig }
                })
            );
        }

        console.debug(`switched from page ${currentActivePage?.pageId} to page ${newActivePage.pageId}`);
    } finally {
        dispatch(setIsActivePageChanging(false));
    }
};

const cleanPageInternalProps = (page: AttachedPageInternal): AttachedPage => {
    const cleanedPage = { ...page };
    cleanedPage.layoutName = cleanedPage.layoutContainerKey;
    delete cleanedPage.layoutContainerKey;
    delete cleanedPage.isLayoutCreated;
    delete cleanedPage.isLayoutReady;
    return cleanedPage;
};

export const setActivePageForWindow: typeof SetActivePageForWindowType =
    makeDebouncedFunc(handleSetActivePageForWindow);

/**
 * Get the page from redux and update the layout for the given page id.
 */
export const getPageWithLayout = async (pageId: string) => {
    if (!pageId) {
        return null;
    }

    const [page, index] = selectPageWithIndex(getState(), pageId);

    if (!page) {
        return null;
    }

    const layout = await getLayoutConfig(page.layoutContainerKey);

    const layoutConfig = page.isLocked
        ? getUnlockedLayout(layout, page.layout) // never store locked layout setttings in memory
        : layout;

    dispatch(
        updatePageAtIndex({
            index,
            page: { layout: layoutConfig }
        })
    );
    await updatePagesWindowOptions();

    return selectPage(getState(), pageId);
};

export const getActivePageForWindow = async () => {
    const { pageId: activePageId } = selectActivePage(getState());
    if (activePageId) {
        return cleanPageInternalProps(await getPageWithLayout(activePageId));
    }

    return null;
};

export const renamePage: typeof RenamePageType = async ({ pageId, newTitle, identity }) => {
    const [page, index] = selectPageWithIndex(getState(), pageId);
    if (!page) {
        throw new Error(`page with id ${pageId} is not attached to window ${identity.name}`);
    }
    dispatch(
        updatePageAtIndex({
            index,
            page: { title: newTitle }
        })
    );
    await updatePagesWindowOptions();
};

export const getPages: typeof GetPagesType = async () => {
    // Ensure we have the latest page layouts in redux state
    await updateInternalPageState();

    const updatedPages = selectPages(getState());
    return updatedPages.map((page) => {
        const cleanedPage = cleanPageInternalProps(page);
        cleanedPage.layout = mapLayoutViewComponents(cleanedPage.layout, mapInternalWorkspaceDataToWorkspacePlatform);
        return cleanedPage;
    });
};

export const attachPagesToWindow: typeof AttachPagesToWindowType = async ({
    pages,
    insertionIndex,
    replaceActivePage
}) => {
    const existingPages = [...selectPages(getState())];

    // Apply correct newTabButton URL to ensure pages from storage have the correct landing page URL
    const newTabButtonUrl = await getEnterpriseLandingUrl();
    pages.forEach((page) => {
        if (page.layout) {
            applyEnterprisePageRequiredLayoutSettings({ newTabButtonUrl }, page.layout);
        }
    });

    await attachPagesToWindowCore({
        pages,
        existingPages,
        insertionIndex,
        replaceActivePage,
        attachPanelViews,
        dispatch,
        updatePagesWindowOptions,
        setPages,
        updatePageAtIndex
    });
};

export const detachPagesFromWindow: typeof DetachPagesFromWindowType = async (payload) => {
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
    const attachedPages = selectPages(getState());
    const detachSet = new Set(payload.pageIds);

    let detachedActivePageIndex = -1;
    const filteredPages = attachedPages.filter(({ pageId, isActive }, index) => {
        const isDetached = detachSet.has(pageId);
        if (isDetached) {
            // Clear tab focus store of state for pages that are being detached
            dispatch(deletePageWithSelectedViews(pageId));
            if (isActive) {
                detachedActivePageIndex = index;
            }
        }
        return !isDetached;
    });

    raiseBrowserPageAnalytics(filteredPages, 'Close Page');

    if (filteredPages.length === 0) {
        getCurrentOFWindow().close(true);
        return;
    }

    if (detachedActivePageIndex !== -1) {
        const newActivePage = getNextActivePageOnRemoval(detachedActivePageIndex, filteredPages);
        // We call the setActivePage override here to allow platform developers to effect page-dependent changes on newly active page.
        await browser.setActivePage(newActivePage.pageId);
    }

    // We now need to update the filteredPages array so the array contains the newly active page, which we set above.
    const updatedFilteredPages = selectPages(getState()).filter((page) => !detachSet.has(page.pageId));
    dispatch(setPages(updatedFilteredPages));

    await updatePagesWindowOptions();
};

export const reorderPagesForWindow: typeof ReorderPagesForWindowType = async ({ pageIds }) => {
    const pages = selectPages(getState());
    const reorderMap: Map<string, AttachedPage> = new Map();
    pages.forEach((page) => reorderMap.set(page.pageId, page));
    const reorderedPages = pageIds.map((pageId) => reorderMap.get(pageId)).filter((v): v is AttachedPage => !!v);
    dispatch(setPages(reorderedPages));
    await updatePagesWindowOptions();
};

export const updatePageForWindow: typeof UpdatePageForWindowType = async ({ pageId, page, identity }) => {
    console.debug(`updating page with id ${pageId}`);

    const [currentPageState, index] = selectPageWithIndex(getState(), pageId);
    if (!page) {
        throw new Error(`page with id ${pageId} is not attached to window ${identity.name}`);
    }

    const anyPayloadPage = page as any;
    delete anyPayloadPage.isActive;
    delete anyPayloadPage.parentIdentity;

    // Have to make a deep clone of the redux page state. Spreading a redux state keeps all properties frozen.
    const newPageState = { ...structuredClone(currentPageState), ...page };

    applyEnterprisePageRequiredLayoutSettings(
        {
            newTabButtonUrl: await getEnterpriseLandingUrl()
        },
        newPageState.layout
    );

    if (page.pageId && page.pageId !== pageId) {
        // If pageId is updated (i.e. in Save As), we should consider this a close & open in analytics
        raiseBrowserPageAnalytics([currentPageState], 'Close Page');
        raiseBrowserPageAnalytics([newPageState], 'Open Page');
    }

    dispatch(updatePageAtIndex({ index, page }));

    updatePagesWindowOptions();

    const isLockedStateChanged = Object.hasOwn(page, 'isLocked') && newPageState.isLocked !== currentPageState.isLocked;
    if (currentPageState.isActive) {
        // Updating the active page's layout or its isLocked property requires replacing current layout
        if (page.layout || isLockedStateChanged) {
            // replacing the layout so need to set the flag to ignore layout events that trigger dirty state
            dispatch(setIsActivePageChanging(true));
            const newLayout = page.layout || currentPageState.layout;
            await replaceLayout(newLayout, newPageState);
            dispatch(setIsActivePageChanging(false));
        }
        // Replace panel views if we're updating the panels object
        if (page.panels) {
            // replacing the layout so need to set the flag to ignore view events that trigger dirty state
            dispatch(setIsActivePageChanging(true));
            await setUpPanelViews(page.panels, currentPageState.panels);
            dispatch(setIsActivePageChanging(false));
        }
    }
};

export const isActivePageChanging = () => selectIsActivePageChanging(getState());

/**
 * Updates pages in redux state with up-to-date layouts
 */
export async function updateInternalPageState() {
    let layoutSnapshot: OpenFin.LayoutSnapshot;
    try {
        layoutSnapshot = await fin.Platform.Layout.getCurrentLayoutManagerSync().getLayoutSnapshot();
    } catch (error) {
        // if window layout isn't initialized yet, no need to update state
    }

    const pages = selectPages(getState());
    if (layoutSnapshot) {
        pages.forEach((page, index) => {
            // when getting pages, return most up-to-date layout (if initialized)
            const currentLayout = layoutSnapshot.layouts[page.layoutContainerKey] || page.layout;
            const updatedLayoutConfig = page.isLocked
                ? getUnlockedLayout(currentLayout, page.layout) // never store locked layout setttings in memory
                : currentLayout;

            dispatch(
                updatePageAtIndex({
                    index,
                    page: { layout: updatedLayoutConfig }
                })
            );
        });
        await updatePagesWindowOptions();
    }
}
