import { getEnterpriseBaseUrl } from '@common/utils/browser-base-url';
import { DefaultSaveMenuBounds } from '@common/utils/context-menu';
import { MenuConfig, ResponseModalConfig, RightMenuConfig } from '@common/utils/menu-config';
import Route from '@common/utils/route';
import { currentOFIdentity, WindowName } from '@common/utils/window';

import { t } from '@common/api/i18next';

type PageCloseMenuOptions = { textInputOptions: { placeholder: string; defaultValue: string }; titlePrefix?: string };

// This menu is being used by waitForModalResponse so is not kept in redux state
export const getPageCloseMenu = async ({
    textInputOptions,
    titlePrefix
}: PageCloseMenuOptions): Promise<ResponseModalConfig> => {
    return {
        title: 'Page Close',
        windowOptions: {
            url: (await getEnterpriseBaseUrl()) + Route.ResponseModal,
            name: WindowName.BrowserMenu,
            defaultHeight: textInputOptions ? 157 : 113,
            defaultWidth: 410,
            modalParentIdentity: currentOFIdentity
        },
        content: {
            title: (titlePrefix || '') + t('modal.saveChangesPrompt'),
            body: t('enterpriseModal.discardSupertabWarning'),
            buttons: {
                left: [
                    {
                        label: t('saveModal.discardChanges'),
                        type: 'secondary',
                        id: 'Discard Changes',
                        variant: 'outline'
                    }
                ],
                right: [
                    { label: t('global.cancel'), type: 'secondary', id: 'Cancel', variant: 'outline' },
                    { label: t('global.save'), type: 'primary', id: 'Save', variant: 'submit' }
                ]
            },
            closeType: 'page',
            textInputOptions
        },
        parameters: new URLSearchParams({ isEnterprise: `${true}` })
    };
};

type WindowCloseMenuOptions = { unsavedPagesCount: number };
// This menu is being used by waitForModalResponse so is not kept in redux state
export const getBrowserWindowCloseMenu = async ({
    unsavedPagesCount
}: WindowCloseMenuOptions): Promise<ResponseModalConfig> => {
    return {
        title: 'Window Close',
        windowOptions: {
            url: (await getEnterpriseBaseUrl()) + Route.ResponseModal,
            name: WindowName.BrowserMenu,
            defaultHeight: 119,
            defaultWidth: 410,
            modalParentIdentity: currentOFIdentity
        },
        content: {
            title: t('enterpriseSaveModal.saveSupertabCount', {
                count: unsavedPagesCount
            }),
            body: t('enterpriseModal.discardSupertabWarning'),
            buttons: {
                left: [{ label: t('saveModal.discardAll'), type: 'secondary', id: 'Discard All' }],
                right: [
                    { label: t('global.cancel'), type: 'secondary', id: 'Cancel' },
                    { label: t('saveModal.saveAll'), type: 'primary', id: 'Save All' }
                ]
            }
        },
        parameters: new URLSearchParams({ isEnterprise: `${true}` })
    };
};

export const getColorLinkingMenu = async (title: string): Promise<RightMenuConfig> => ({
    title,
    windowOptions: {
        url: (await getEnterpriseBaseUrl()) + Route.BrowserPopupMenuColorLinking,
        name: WindowName.BrowserMenu,
        defaultHeight: 37,
        defaultWidth: 226
    }
});

export const getLayoutsMenu = async (title: string): Promise<RightMenuConfig> => ({
    title,
    windowOptions: {
        url: (await getEnterpriseBaseUrl()) + Route.BrowserPopupMenuLayouts,
        name: WindowName.BrowserMenu,
        defaultHeight: 37,
        defaultWidth: 138
    }
});

export const getSaveMenu = async (): Promise<MenuConfig> => ({
    title: t('toolbar.saveMenu'),
    windowOptions: {
        url: (await getEnterpriseBaseUrl()) + Route.BrowserPopupMenuSaveModal,
        name: WindowName.BrowserSaveMenu,
        defaultWidth: DefaultSaveMenuBounds.width,
        defaultHeight: DefaultSaveMenuBounds.height
    }
});
