import type OpenFin from '@openfin/core';

const viewExists = async (name: string, uuid: string): Promise<OpenFin.View | undefined> => {
    const app = fin.Application.getCurrentSync();
    const views = await app.getViews();

    const view = views.find((v) => v.identity.name === name && v.identity.uuid === uuid);

    if (!view) {
        return undefined;
    }

    return fin.View.wrapSync(view.identity);
};

const waitForViewCreated = (name: string, uuid: string, timeoutMs = 5000): Promise<OpenFin.View> => {
    const view = fin.View.wrapSync({ name, uuid });

    return new Promise<OpenFin.View>((resolve, reject) => {
        let settled = false;
        let timeout: ReturnType<typeof setTimeout> | null = null;

        const onCreated = () => {
            if (settled) {
                return;
            }

            settled = true;
            clearTimeout(timeout);
            resolve(view);
        };

        timeout = setTimeout(() => {
            if (settled) {
                return;
            }

            settled = true;
            view.removeListener('created', onCreated);
            reject(new Error(`Panel view "${name}" was not created within ${timeoutMs}ms`));
        }, timeoutMs);

        view.once('created', onCreated);
    });
};

/**
 * Resolves with the requested view once it exists in the runtime. First checks
 * whether the view is already available; if not, subscribes to the platform's
 * `view-created` event and resolves when the matching view appears. A timeout
 * guard rejects if the view isn't created within `timeoutMs`.
 */
export const waitForView = async (name: string, uuid: string, timeoutMs = 5000): Promise<OpenFin.View> => {
    const viewCreatedPromise = waitForViewCreated(name, uuid, timeoutMs);
    const view = await viewExists(name, uuid);

    if (!view) {
        return await viewCreatedPromise;
    }

    // View already exists — suppress the unused promise's eventual timeout rejection
    viewCreatedPromise.catch(() => {
        // noop
    });

    return view;
};
