import type OpenFin from '@openfin/core';

import { WindowName } from '@common/utils/window';

import type { Page } from '@common/api/pages/shapes';

import type { BrowserSnapshot, BrowserWorkspacePlatformWindowOptions } from '..';

export const filterSnapshotWindows = (win: OpenFin.WindowOptions) => {
    const isHome = win.name === WindowName.Home;
    const isHomeInternal = win.name?.startsWith(WindowName.HomeInternal);
    const isInternalMenu =
        win.name?.startsWith(WindowName.BrowserMenu) ||
        win.name?.startsWith(WindowName.BrowserSaveMenu) ||
        win.name?.startsWith(WindowName.DockSaveWorkspaceMenu);
    return !isHome && !isHomeInternal && !isInternalMenu;
};

/**
 * fitToMonitor()
 * Function to determine if window size is too large
 * for available rectangle area.
 *
 * - Checks monitor data for available rectangle coords
 * - Defines max width/height for current monitor
 * - Defines default width/height if property is not set
 * - Updates options object default width/height if they exceed max values
 *
 * Ticket: WRK-1084
 *
 * @param options - Object passed into createWindow -> contains height and width
 * @returns unprocessed or processed options object
 */
export const fitToMonitor = async (options: OpenFin.PlatformWindowCreationOptions) => {
    const monitorInfo = await fin.System.getMonitorInfo();

    // Determine if the window is on the primary or a secondary monitor
    let targetMonitor = monitorInfo.primaryMonitor;
    const windowPosition = { x: options.defaultLeft, y: options.defaultTop };

    // Check against nonPrimaryMonitors if the window is within their bounds
    monitorInfo.nonPrimaryMonitors.forEach((monitor) => {
        const { top, bottom, left, right } = monitor.availableRect;
        if (
            windowPosition.x >= left &&
            windowPosition.x <= right &&
            windowPosition.y >= top &&
            windowPosition.y <= bottom
        ) {
            targetMonitor = monitor;
        }
    });

    // Adjust window size based on the target monitor's availableRect
    const maxHeight = targetMonitor.availableRect.bottom - targetMonitor.availableRect.top;
    const maxWidth = targetMonitor.availableRect.right - targetMonitor.availableRect.left;

    options.defaultHeight = Math.min(options.defaultHeight || 800, maxHeight);
    options.defaultWidth = Math.min(options.defaultWidth || 800, maxWidth);

    return options;
};

type LegacyWindowOptions = Omit<OpenFin.PlatformWindowCreationOptions, 'workspacePlatform'> & {
    pages?: Page[];
    workstacks?: Page[];
};

const migrateLegacyOptions = ({
    workstacks,
    pages,
    ...rest
}: LegacyWindowOptions): OpenFin.PlatformWindowCreationOptions => {
    return { ...rest, workspacePlatform: { pages: pages || workstacks || null } };
};

export const initWorkspacePlatformOptions = (
    options: LegacyWindowOptions | OpenFin.PlatformWindowCreationOptions
): OpenFin.PlatformWindowCreationOptions => {
    if ('workspacePlatform' in options) return options;

    return migrateLegacyOptions(options);
};

export type WindowType = 'browser' | 'platform' | 'classic' | 'mixed' | 'enterprise';

/**
 * checkHasBrowserWindows
 * Determines whether the snapshot has browser windows.
 *
 * @param snapshot - The snapshot to check.
 *
 * @returns - Whether the snapshot has browser windows.
 */
export function checkHasBrowserWindows(snapshot: BrowserSnapshot): boolean {
    for (const snapshotWin of snapshot.windows) {
        if ((snapshotWin.workspacePlatform as any)?.pages?.length) {
            return true;
        }
    }
    return false;
}

export const copyObject = <T>(obj: T): T => {
    return JSON.parse(JSON.stringify(obj));
};

export function validateTabDimensionsIfAny(overrideOptions: OpenFin.PlatformWindowCreationOptions) {
    const viewTabDimensions = overrideOptions.workspacePlatform
        ?.viewTabDimensions as BrowserWorkspacePlatformWindowOptions['viewTabDimensions'];
    const pageTabDimensions = overrideOptions.workspacePlatform
        ?.pageTabDimensions as BrowserWorkspacePlatformWindowOptions['pageTabDimensions'];

    const valueFormatRegex = /^[0-9]+(px|%)$/;
    if (viewTabDimensions) {
        if (viewTabDimensions.minWidth && !valueFormatRegex.test(viewTabDimensions.minWidth)) {
            throw new Error(
                `Provided viewTabDimensions.min value "${viewTabDimensions.minWidth}" is not in a supported format.`
            );
        }
        if (viewTabDimensions.maxWidth && !valueFormatRegex.test(viewTabDimensions.maxWidth)) {
            throw new Error(
                `Provided viewTabDimensions.max value "${viewTabDimensions.maxWidth}" is not in a supported format.`
            );
        }
    }
    if (pageTabDimensions) {
        if (pageTabDimensions.minWidth && !valueFormatRegex.test(pageTabDimensions.minWidth)) {
            throw new Error(
                `Provided pageTabDimensions.min value "${pageTabDimensions.minWidth}" is not in a supported format.`
            );
        }
        if (pageTabDimensions.maxWidth && !valueFormatRegex.test(pageTabDimensions.maxWidth)) {
            throw new Error(
                `Provided pageTabDimensions.max value "${pageTabDimensions.maxWidth}" is not in a supported format.`
            );
        }
    }
}
